#include "Epidemic/GameFramework/Perception/perception.h"
using namespace epidemic::gameplay;using namespace epidemic::gameplay::perception;
int main(){PerceptionService s;auto hearing=SenseTypeId::FromString("framework.sense.hearing");SenseDefinition hear;hear.id=hearing;hear.canonical_name="framework.sense.hearing";hear.base_range_mm=10000;if(!s.RegisterSense(hear))return 1;GameplayObjectRef npc{GameplayDomainId::FromString("test.entity"),GameplayObjectId::FromString("npc")};GameplayObjectRef player{GameplayDomainId::FromString("test.entity"),GameplayObjectId::FromString("player")};PerceiverProfile p;p.id=PerceiverProfileId::FromString("test.npc.perception");p.subject=npc;p.canonical_name="test.npc.perception";p.senses={hearing};if(!s.RegisterProfile(p))return 2;s.Freeze();PerceptionStimulus stim;stim.sense=hearing;stim.source=player;stim.position={1000,0,0};stim.strength_micro=900000;stim.created_at={0};stim.lifetime={10};auto sid=s.CreateStimulus(stim);if(!sid)return 3;auto out=s.ProcessStimulus(sid.Value(),{1});if(!out||out.Value().size()!=1)return 4;if(out.Value()[0].perceiver!=npc)return 5;auto* aw=s.GetAwareness(npc,player);if(!aw||aw->level<AwarenessLevel::Aware)return 6;if(s.FindObservationsByPerceiver(npc).size()!=1)return 7;auto snap=s.CaptureSnapshot();PerceptionService r;if(!r.RegisterSense(hear))return 8;r.Freeze();if(!r.RestoreSnapshot(std::move(snap)))return 9;if(!r.GetAwareness(npc,player))return 10;if(!r.ExpireStimuli({20}))return 11;if(!r.FindStimuliInArea({}).empty())return 12;return 0;}
